func agreementProseP1Physical(body string, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementZeroActiveDiagnosticOwner, bool) {
	physical, _ := agreementZeroActiveDiagnosticPhysical(body, check, tree, target)
	if !tree.Valid {
		return physical, false
	}
	seen := map[int]bool{}
	for oi := range physical {
		o := physical[oi]
		seen[o.Field] = true
	}
	for fi, f := range check.Fields {
		if seen[fi] || f.Code || f.Comment || f.Escaped || len(f.Targets) != 1 || f.Targets[0] != target {
			continue
		}
		matches := 0
		var declaration agreementUnusedParagraphDiagnosticOwner
		for root, nodes := range tree.Trees {
			for node, n := range nodes {
				if n.Kind != "Paragraph" && n.Kind != "TextBlock" {
					continue
				}
				for li, line := range n.Lines {
					if line.Start <= f.Span.Start && f.Span.Stop <= line.Stop {
						matches++
						declaration = agreementUnusedParagraphDiagnosticOwner{Field: fi, Definition: -1, Root: root, Node: node, Line: li}
					}
				}
			}
		}
		if matches == 1 {
			physical = append(physical, agreementZeroActiveDiagnosticOwner{Field: fi, Family: "native-prose-line", Paragraph: declaration})
		}
	}
	slices.SortFunc(physical, func(a, b agreementZeroActiveDiagnosticOwner) int { return a.Field - b.Field })
	return physical, len(physical) > 0
}

func agreementProseP1PrivateSingle(body, target string, o *agreementZeroActiveDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	if o.Family != "native-prose-line" {
		return agreementZeroActiveDiagnosticPrivate(body, target, []agreementZeroActiveDiagnosticOwner{*o}, check)
	}
	if o.Field < 0 || o.Field >= len(check.Fields) || target == "" || strings.Contains(body, "q") {
		return "", nil, false
	}
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, valid := agreementProseP1Physical(body, check, &tree, target)
	if !valid || !slices.Contains(physical, *o) {
		return "", nil, false
	}
	f := check.Fields[o.Field]
	if f.Span.Start < 0 || f.Span.Stop > len(body) || f.Span.Stop <= f.Span.Start || body[f.Span.Start:f.Span.Stop] != f.Word || !strings.HasPrefix(f.Word, "[[") || !strings.HasSuffix(f.Word, "]]") {
		return "", nil, false
	}
	inner := f.Word[2 : len(f.Word)-2]
	link, ok := graph.ParseWikilink(strings.ReplaceAll(inner, "\\|", "|"))
	if !ok || link.Target != target || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
		return "", nil, false
	}
	start := f.Span.Start + 2 + strings.Index(inner, target)
	stop := start + len(target)
	if start < f.Span.Start+2 || stop > f.Span.Stop-2 || body[start:stop] != target {
		return "", nil, false
	}
	change := agreementMixedRename{Field: o.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: strings.Repeat("q", len(target))}
	b := []byte(body)
	copy(b[start:stop], change.New)
	return string(b), []agreementMixedRename{change}, true
}
func agreementProseP1Private(body, target string, owners []agreementZeroActiveDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementProseP1Physical(body, check, &tree, target)
	if !ok || len(owners) == 0 {
		return "", nil, false
	}
	bodyBytes := []byte(body)
	changes := []agreementMixedRename{}
	seen := map[int]bool{}
	for oi := range owners {
		o := owners[oi]
		if seen[o.Field] || !slices.Contains(physical, o) {
			return "", nil, false
		}
		seen[o.Field] = true
		_, one, valid := agreementProseP1PrivateSingle(body, target, &o, check)
		if !valid || len(one) != 1 {
			return "", nil, false
		}
		c := one[0]
		copy(bodyBytes[c.Span.Start:c.Span.Stop], c.New)
		changes = append(changes, c)
	}
	return string(bodyBytes), changes, true
}

func agreementProseP1Producers(t *testing.T, body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) agreementDiagnosticProducerReading {
	t.Helper()
	tree := agreementNativeProseAddressTreeReading(body, nil)
	physical, ok := agreementProseP1Physical(body, check, &tree, target)
	if !ok {
		return agreementDiagnosticProducerReading{Physical: physical}
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return agreementDiagnosticProducerReading{Physical: physical}
	}
	owners := []agreementZeroActiveDiagnosticOwner{}
	changes := []agreementMixedRename{}
	singles := []agreementZeroActiveDiagnosticSingle{}
	whole := []byte(body)
	expected := slices.Clone(raw.Diagnostics)
	used := map[int]bool{}
	for owneri := range physical {
		owner := physical[owneri]
		if owner.Field < 0 || owner.Field >= len(check.Fields) || check.Fields[owner.Field].Code {
			continue
		}
		private, one, valid := agreementProseP1PrivateSingle(body, target, &owner, check)
		if !valid || len(one) != 1 {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		part, good := agreementCodeWindowParts(pr.HTML)
		if !good || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, part) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		valid = true
		for i := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[i], pr.Diagnostics[i]) {
				continue
			}
			if index >= 0 {
				valid = false
				break
			}
			index = i
		}
		if !valid {
			continue
		}
		if index >= 0 {
			a, b := raw.Diagnostics[index], pr.Diagnostics[index]
			if used[index] || a.Kind != render.DiagWikilinkBroken || a.Target != target || b.Target != one[0].New || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, strconv.Quote(target), strconv.Quote(one[0].New)) {
				continue
			}
			used[index] = true
			expected[index] = b
		}
		owners = append(owners, owner)
		changes = append(changes, one[0])
		copy(whole[one[0].Span.Start:one[0].Span.Stop], one[0].New)
		singles = append(singles, agreementZeroActiveDiagnosticSingle{Field: owner.Field, Index: index, Start: one[0].Span.Start, Body: private, Diagnostics: pr.Diagnostics})
	}
	return agreementDiagnosticProducerReading{Physical: physical, Owners: owners, Changes: changes, Private: string(whole), Diagnostics: expected, Singles: singles, Valid: len(owners) > 0}
}

func agreementProseP1Projection(r *agreementProseP1Declaration, before, after []agreementFailure, privateDiagnostics []render.Diagnostic) bool {
	if r == nil || (r.Signatures != nil && !maps.Equal(agreementMixedCurrent(before), r.Signatures)) || (r.PrivateSignatures != nil && !maps.Equal(agreementMixedCurrent(after), r.PrivateSignatures)) || r.Active < 1 || r.Active != len(r.Owners) || len(r.Singles) != len(r.Owners) || len(r.Changes) != len(r.Owners) || !cmp.Equal(privateDiagnostics, r.PrivateDiagnostics) {
		return false
	}
	var selected *agreementFailure
	for i := range before {
		if agreementSignature(&before[i]) == r.Selected {
			if selected != nil {
				return false
			}
			selected = &before[i]
		}
	}
	if selected == nil || selected.Property != "P1" || selected.Direction != "judge-only" || selected.Multiplicity != r.Active || selected.Tuple.Target != r.Target {
		return false
	}
	expected := slices.Clone(r.Diagnostics)
	whole := []byte(r.Body)
	seen := map[int]bool{}
	fields := map[int]bool{}
	for i := range r.Owners {
		o, c, s := r.Owners[i], r.Changes[i], r.Singles[i]
		if o.Field < 0 || o.Field >= len(r.Check.Fields) || fields[o.Field] || r.Check.Fields[o.Field].Code || c.Field != o.Field || s.Field != o.Field || s.Start != c.Span.Start || c.Span.Start < 0 || c.Span.Stop > len(r.Body) || c.Span.Stop <= c.Span.Start || r.Body[c.Span.Start:c.Span.Stop] != r.Target || c.Old != r.Target || c.New != strings.Repeat("q", len(r.Target)) || len(s.Diagnostics) != len(r.Diagnostics) {
			return false
		}
		fields[o.Field] = true
		single := []byte(r.Body)
		copy(single[c.Span.Start:c.Span.Stop], c.New)
		if string(single) != s.Body {
			return false
		}
		copy(whole[c.Span.Start:c.Span.Stop], c.New)
		for di, d := range r.Diagnostics {
			p := s.Diagnostics[di]
			if di != s.Index {
				if !cmp.Equal(d, p) {
					return false
				}
				continue
			}
			if seen[di] || d.Kind != render.DiagWikilinkBroken || d.Target != r.Target || p.Target != c.New || d.Kind != p.Kind || d.Section != p.Section || d.Block != p.Block || p.Message != strings.ReplaceAll(d.Message, strconv.Quote(r.Target), strconv.Quote(c.New)) {
				return false
			}
			seen[di] = true
			expected[di] = p
		}
		if s.Index < -1 || s.Index >= len(r.Diagnostics) {
			return false
		}
	}
	if string(whole) != r.Private || !cmp.Equal(expected, r.PrivateDiagnostics) {
		return false
	}
	old, newCounts := map[string]int{}, map[string]int{}
	for _, n := range r.Targets {
		old[n]++
	}
	for _, n := range r.PrivateTargets {
		newCounts[n]++
	}
	replacement := strings.Repeat("q", len(r.Target))
	if old[r.Target]-newCounts[r.Target] != r.Active || newCounts[replacement]-old[replacement] != r.Active || old[replacement] != 0 {
		return false
	}
	delete(old, r.Target)
	delete(old, replacement)
	delete(newCounts, r.Target)
	delete(newCounts, replacement)
	if !maps.Equal(old, newCounts) {
		return false
	}
	projectedRaw := render.Result{}
	projectedRaw.Diagnostics = expected
	p0 := agreementPageFailures(r.Body, &projectedRaw, &r.Page)
	want := maps.Clone(agreementMixedCurrent(before))
	for fi := range before {
		f := before[fi]
		if f.Property == "P0" || f.Property == "P3" {
			delete(want, agreementSignature(&f))
		}
	}
	for fi := range p0 {
		f := p0[fi]
		if f.Property == "P0" {
			want[agreementSignature(&f)]++
		}
	}
	delete(want, r.Selected)
	renamed := *selected
	renamed.Tuple.Target = replacement
	want[agreementSignature(&renamed)]++
	actual := map[string]int{}
	for fi := range after {
		f := after[fi]
		if f.Property != "P3" {
			actual[agreementSignature(&f)]++
		}
	}
	return maps.Equal(want, actual) && agreementZeroActiveDiagnosticCutProjection(r.Body, r.Private, r.Changes, before, after)
}

func agreementProseP1Difference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P1" || f.Identity != "citation-occurrences" || f.Direction != "judge-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.Section != "" || f.Tuple.State != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementProseP1Declarations()
	for i := range records {
		r := &records[i]
		if r.Body != c.Body || r.Target != f.Tuple.Target {
			continue
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, ok := agreementCodeWindowParts(raw)
		physical, pok := agreementProseP1Physical(c.Body, &check, &tree, r.Target)
		private, changes, valid := agreementProseP1Private(c.Body, r.Target, r.Owners, &check)
		if agreementSignature(f) != r.Selected || !ok || !pok || !valid || private != r.Private || !cmp.Equal(changes, r.Changes) || !cmp.Equal(physical, r.Physical) || !cmp.Equal(native, r.Native) || !cmp.Equal(check, r.Check) || !cmp.Equal(tree, r.Tree) || !cmp.Equal(parts, r.Parts) || raw != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), r.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), r.HTMLSites) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(c.Body), r.Removed) || !cmp.Equal(judge.LinkTargets(c.Body), r.Targets) || !maps.Equal(agreementMixedCurrent(failures), r.Signatures) || !agreementProseP1Projection(r, failures, r.After, r.PrivateDiagnostics) {
			return "", "", ""
		}
		authority = "#1011 stage 5"
		for oi := range r.Owners {
			o := r.Owners[oi]
			if o.Family == "native-info" {
				authority = "#1011 stages 4 and 5"
			}
		}
		return "debt", authority, "judge"
	}
	return "", "", ""
}

func agreementProseP1Failures(t *testing.T, body string) (render.Result, agreementHTML, []agreementFailure) {
	t.Helper()
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	failures := agreementPageFailures(body, &raw, &page)
	failures = append(failures, agreementFragmentFailures(t, []agreementCase{{Body: body}}, []agreementHTML{page})[0]...)
	return raw, page, failures
}

func TestAgreementProseP1OwnedSource(t *testing.T) {
	records := agreementProseP1Declarations()
	if len(records) != 47 {
		t.Fatal("caught: whole native prose P1 declarations")
	}
	for i := range records {
		r := &records[i]
		t.Run(r.Case+"/"+r.Target, func(t *testing.T) {
			native := agreementNativeOwnerReading(r.Body)
			check := agreementNativeCheckReading(r.Body, native)
			reading := agreementProseP1Producers(t, r.Body, r.Target, native, &check)
			physical, owners, changes, private, diagnostics, singles, ok := reading.Physical, reading.Owners, reading.Changes, reading.Private, reading.Diagnostics, reading.Singles, reading.Valid
			if !ok || !cmp.Equal(physical, r.Physical) || !cmp.Equal(owners, r.Owners) || !cmp.Equal(changes, r.Changes) || private != r.Private || !cmp.Equal(diagnostics, r.PrivateDiagnostics) || !cmp.Equal(singles, r.Singles) {
				t.Fatal("caught: complete native prose P1 physical source and single-field declarations")
			}
			raw, page, before := agreementProseP1Failures(t, r.Body)
			pr, pp, after := agreementProseP1Failures(t, r.Private)
			if raw.HTML != r.HTML || pr.HTML != r.PrivateHTML || raw.HTML != pr.HTML || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !cmp.Equal(pr.Diagnostics, r.PrivateDiagnostics) || !cmp.Equal(page, r.Page) || !cmp.Equal(pp, r.PrivatePage) || !cmp.Equal(page, pp) || !maps.Equal(agreementMixedCurrent(before), r.Signatures) || !maps.Equal(agreementMixedCurrent(after), r.PrivateSignatures) || !agreementProseP1Projection(r, before, after, pr.Diagnostics) {
				t.Fatal("caught: complete native prose P1 original and private public signed ledgers")
			}
			parts, partsOK := agreementCodeWindowParts(raw.HTML)
			privateParts, privateOK := agreementCodeWindowParts(pr.HTML)
			if !partsOK || !privateOK || !cmp.Equal(parts, r.Parts) || !cmp.Equal(privateParts, r.PrivateParts) || !cmp.Equal(agreementNativeCodePayloadSites(r.Private), r.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(r.Private), r.HTMLSites) || !cmp.Equal(native, r.Native) || !cmp.Equal(agreementNativeOwnerReading(r.Private), r.PrivateNative) || !cmp.Equal(check, r.Check) || !cmp.Equal(agreementNativeCheckReading(r.Private, r.PrivateNative), r.PrivateCheck) || !cmp.Equal(agreementNativeProseAddressTreeReading(r.Body, nil), r.Tree) || !cmp.Equal(agreementNativeProseAddressTreeReading(r.Private, nil), r.PrivateTree) || !cmp.Equal(agreementRemovedCommentDiagnosticRead(r.Private), r.PrivateRemoved) || !cmp.Equal(judge.LinkTargets(r.Private), r.PrivateTargets) {
				t.Fatal("caught: whole native prose P1 original and private reader declarations")
			}
			for _, s := range r.Singles {
				sr, sp := agreementIsolatedPage(t, agreementCase{Body: s.Body})
				parts, valid := agreementCodeWindowParts(sr.HTML)
				if !valid || sr.HTML != raw.HTML || !cmp.Equal(sr.Diagnostics, s.Diagnostics) || !cmp.Equal(sp, r.Page) || !cmp.Equal(parts, r.Parts) || !cmp.Equal(agreementNativeOwnerReading(s.Body), r.Native) || !cmp.Equal(agreementNativeProseAddressTreeReading(s.Body, nil), r.Tree) {
					t.Fatal("caught: independent native prose P1 single-field public observation")
				}
			}
			count := 0
			for fi := range before {
				f := before[fi]
				if agreementSignature(&f) != r.Selected {
					continue
				}
				count++
				k, a, w := agreementProseP1Difference(agreementCase{Body: r.Body}, &f, raw.HTML, &page, raw.Diagnostics, before)
				want := "#1011 stage 5"
				for oi := range r.Owners {
					o := r.Owners[oi]
					if o.Family == "native-info" {
						want = "#1011 stages 4 and 5"
					}
				}
				if k != "debt" || a != want || w != "judge" {
					t.Fatal("caught: complete native prose P1 declared authority")
				}
			}
			if count != 1 {
				t.Fatal("caught: unique complete native prose P1 selected signature")
			}
		})
	}
}

func TestAgreementProseP1OwnedRefusals(t *testing.T) {
	for i := range agreementProseP1Declarations() {
		r := &agreementProseP1Declarations()[i]
		t.Run(r.Case+"/"+r.Target, func(t *testing.T) {
			raw, page, failures := agreementProseP1Failures(t, r.Body)
			var selected agreementFailure
			found := 0
			for _, f := range failures {
				if agreementSignature(&f) == r.Selected {
					selected = f
					found++
				}
			}
			if found != 1 {
				t.Fatal("selected native prose P1 setup")
			}
			refuse := func(c agreementCase, f *agreementFailure, html string, p *agreementHTML, d []render.Diagnostic, fs []agreementFailure) {
				t.Helper()
				k, a, w := agreementProseP1Difference(c, f, html, p, d, fs)
				if k != "" || a != "" || w != "" {
					t.Fatal("caught: exact native prose P1 membership and full public context")
				}
			}
			refuse(agreementCase{Body: r.Body}, nil, raw.HTML, &page, raw.Diagnostics, failures)
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, nil, raw.Diagnostics, failures)
			mutations := []struct {
				name   string
				change func(*agreementFailure)
			}{
				{"property", func(f *agreementFailure) { f.Property = "P0" }}, {"identity", func(f *agreementFailure) { f.Identity += "!" }}, {"direction", func(f *agreementFailure) { f.Direction = "page-only" }}, {"count", func(f *agreementFailure) { f.Multiplicity++ }}, {"target", func(f *agreementFailure) { f.Tuple.Target = "q" }}, {"role", func(f *agreementFailure) { f.Tuple.SourceRole = "image" }}, {"section", func(f *agreementFailure) { f.Tuple.Section = "A" }}, {"state", func(f *agreementFailure) { f.Tuple.State = "other" }}, {"fragment", func(f *agreementFailure) { f.Fragment = "^a" }}, {"cut", func(f *agreementFailure) { f.Cut = "text" }}, {"page", func(f *agreementFailure) { f.PagePresent = true }}, {"judge", func(f *agreementFailure) { f.JudgeAccepted = true }}, {"excerpt", func(f *agreementFailure) { f.ExcerptFound = true }},
			}
			for _, m := range mutations {
				t.Run(m.name, func(t *testing.T) {
					f := selected
					m.change(&f)
					refuse(agreementCase{Body: r.Body}, &f, raw.HTML, &page, raw.Diagnostics, failures)
				})
			}
			refuse(agreementCase{Body: r.Body + "!"}, &selected, raw.HTML, &page, raw.Diagnostics, failures)
			refuse(agreementCase{Body: r.Body, Title: "other"}, &selected, raw.HTML, &page, raw.Diagnostics, failures)
			refuse(agreementCase{Body: r.Body, Companions: capturedBodies{"outside.md": "other"}}, &selected, raw.HTML, &page, raw.Diagnostics, failures)
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML+"!", &page, raw.Diagnostics, failures)
			changedPage := page
			changedPage.Blocks = append(slices.Clone(page.Blocks), "^outside")
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &changedPage, raw.Diagnostics, failures)
			changedDiags := append(slices.Clone(raw.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, changedDiags, failures)
			for fi := range failures {
				missing := slices.Delete(slices.Clone(failures), fi, fi+1)
				refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, missing)
				changed := slices.Clone(failures)
				changed[fi].Multiplicity++
				refuse(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, changed)
			}
		})
	}
}

func TestAgreementProseP1OwnedSignedProjection(t *testing.T) {
	for i := range agreementProseP1Declarations() {
		r := &agreementProseP1Declarations()[i]
		t.Run(r.Case+"/"+r.Target, func(t *testing.T) {
			if !agreementProseP1Projection(r, r.Before, r.After, r.PrivateDiagnostics) {
				t.Fatal("caught: whole native prose P1 signed projection")
			}
			for fi := range r.After {
				missing := slices.Delete(slices.Clone(r.After), fi, fi+1)
				if agreementProseP1Projection(r, r.Before, missing, r.PrivateDiagnostics) {
					t.Fatal("caught: every private native prose P1 signed receipt retained")
				}
				changed := slices.Clone(r.After)
				changed[fi].Multiplicity++
				if agreementProseP1Projection(r, r.Before, changed, r.PrivateDiagnostics) {
					t.Fatal("caught: every native prose P1 signed multiplicity retained")
				}
			}
			for fi := range r.Before {
				missing := slices.Delete(slices.Clone(r.Before), fi, fi+1)
				if agreementProseP1Projection(r, missing, r.After, r.PrivateDiagnostics) {
					t.Fatal("caught: every original native prose P1 signed receipt retained")
				}
			}
			for ci := range r.Changes {
				changed := *r
				changed.Changes = slices.Delete(slices.Clone(r.Changes), ci, ci+1)
				if agreementProseP1Projection(&changed, r.Before, r.After, r.PrivateDiagnostics) {
					t.Fatal("caught: whole native prose P1 owned target interval set")
				}
			}
		})
	}
}

func TestAgreementProseP1OwnedWholeSet(t *testing.T) {
	records := agreementProseP1Declarations()
	bodies := map[string]bool{}
	pairs := map[[2]string]bool{}
	fields, silent, info := 0, 0, 0
	for _, r := range records {
		bodies[r.Body] = true
		key := [2]string{r.Body, r.Target}
		if pairs[key] {
			t.Fatal("caught: unique native prose P1 declaration")
		}
		pairs[key] = true
		fields += len(r.Owners)
		for _, s := range r.Singles {
			if s.Index == -1 {
				silent++
			}
		}
		for oi := range r.Owners {
			o := r.Owners[oi]
			if o.Family == "native-info" {
				info++
			}
		}
	}
	if len(records) != 47 || len(bodies) != 44 || len(pairs) != 47 || fields != 65 || silent != 36 || info != 4 {
		t.Fatal("caught: complete native prose P1 body, target, physical field, silent field and mixed info sets")
	}
}

